cd /work/workspace/documents && (command -v pdftotext && pdftotext employment_agreement_excerpt.pdf -) 2>/dev/null || python3 -c "
import sys
try:
    import fitz
    doc = fitz.open('employment_agreement_excerpt.pdf')
    for p in doc: print(p.get_text())
except ImportError:
    try:
        from pypdf import PdfReader
    except ImportError:
        from PyPDF2 import PdfReader
    r = PdfReader('employment_agreement_excerpt.pdf')
    for pg in r.pages: print(pg.extract_text())
"

